// Generated by scripts/make_testdata.py from Photoly's Python path.
type reference struct {
	Images map[string]struct {
		RGBSha256 string    `json:"rgbSha256"`
		Vector    []float32 `json:"vector"`
	} `json:"images"`
	Queries map[string]struct {
		Expected string    `json:"expected"`
		Vector   []float32 `json:"vector"`
	} `json:"queries"`
	Tokens map[string][]int32 `json:"tokens"`
}

const fixtureDir = "../../photoly_server/internal/ai/testdata/ai"

func loadReference(t *testing.T) reference {
	t.Helper()
	raw, err := os.ReadFile("testdata/reference.json")
	if err != nil {
		t.Fatal(err)
	}
	var ref reference
	if err := json.Unmarshal(raw, &ref); err != nil {
		t.Fatal(err)
	}
	return ref
}

func readFixture(t *testing.T, name string) []byte {
	t.Helper()
	data, err := os.ReadFile(filepath.Join(fixtureDir, name))
	if err != nil {
		t.Skipf("fixtures not available: %v", err)
	}
	return data
}

// Lossless fixtures must give the same 224 x 224 bytes as Pillow. JPEG decoders differ
// slightly, so rocket.jpg is checked through its vector in embed_test.go instead.
func TestPreprocessMatchesPillow(t *testing.T) {
	for name, want := range loadReference(t).Images {
		if filepath.Ext(name) != ".png" {
			continue
		}
		rgb, w, h, err := decodeRGB(readFixture(t, name))
		if err != nil {
			t.Fatal(err)
		}
		sum := sha256.Sum256(resizeBilinear(rgb, w, h, imageSize, imageSize))
		if got := hex.EncodeToString(sum[:]); got != want.RGBSha256 {
			t.Errorf("%s: resized RGB differs from Pillow", name)
		}
	}
}

func TestTransparentBecomesWhite(t *testing.T) {
	img := image.NewNRGBA(image.Rect(0, 0, 2, 1))
	img.Set(1, 0, color.NRGBA{0, 0, 0, 255})
	var buf bytes.Buffer
	if err := png.Encode(&buf, img); err != nil {
		t.Fatal(err)
	}
	rgb, _, _, err := decodeRGB(buf.Bytes())
	if err != nil {
		t.Fatal(err)
	}
	if want := []uint8{255, 255, 255, 0, 0, 0}; !slices.Equal(rgb, want) {
		t.Fatalf("got %v, want %v", rgb, want)
	}
}

// A 3 x 2 image with distinct pixels, read back after each EXIF orientation.
func TestOrient(t *testing.T) {
	px := func(v ...uint8) []uint8 {
		out := []uint8{}
		for _, x := range v {
			out = append(out, x, x, x)
		}
		return out
	}
	src := px(1, 2, 3, 4, 5, 6) // 1 2 3 / 4 5 6
	for o, want := range map[int][]uint8{
		1: px(1, 2, 3, 4, 5, 6),
		2: px(3, 2, 1, 6, 5, 4),
		3: px(6, 5, 4, 3, 2, 1),
		4: px(4, 5, 6, 1, 2, 3),
		5: px(1, 4, 2, 5, 3, 6),
		6: px(4, 1, 5, 2, 6, 3),
		7: px(6, 3, 5, 2, 4, 1),
		8: px(3, 6, 2, 5, 1, 4),
	} {
		got, w, h := orient(src, 3, 2, o)
		if !slices.Equal(got, want) || (o >= 5) != (w == 2 && h == 3) {
			t.Errorf("orientation %d: got %v (%dx%d), want %v", o, got, w, h, want)
		}
	}
}

func TestExifOrientation(t *testing.T) {
	var buf bytes.Buffer
	if err := jpeg.Encode(&buf, image.NewGray(image.Rect(0, 0, 3, 2)), nil); err != nil {
		t.Fatal(err)
	}
	plain := buf.Bytes()
	if o := exifOrientation(plain); o != 1 {
		t.Fatalf("no EXIF: got %d", o)
	}
	for _, order := range []binary.AppendByteOrder{binary.BigEndian, binary.LittleEndian} {
		tiff := []byte("MM\x00\x2a")
		if order == binary.LittleEndian {
			tiff = []byte("II\x2a\x00")
		}
		tiff = order.AppendUint32(tiff, 8)
		tiff = order.AppendUint16(tiff, 1)      // one entry
		tiff = order.AppendUint16(tiff, 0x0112) // orientation
		tiff = order.AppendUint16(tiff, 3)      // SHORT
		tiff = order.AppendUint32(tiff, 1)      // count
		tiff = append(order.AppendUint16(tiff, 6), 0, 0)
		seg := append([]byte("Exif\x00\x00"), tiff...)
		app1 := append([]byte{0xFF, 0xE1}, binary.BigEndian.AppendUint16(nil, uint16(len(seg)+2))...)
		withExif := slices.Concat(plain[:2], app1, seg, plain[2:])
		if o := exifOrientation(withExif); o != 6 {
			t.Fatalf("%v: got orientation %d, want 6", order, o)
		}
		_, w, h, err := decodeRGB(withExif)
		if err != nil || w != 2 || h != 3 {
			t.Fatalf("%v: decoded %dx%d (%v), want 2x3", order, w, h, err)
		}
	}
	for _, junk := range [][]byte{nil, {0xFF, 0xD8}, {0xFF, 0xD8, 0xFF, 0xE1, 0xFF, 0xFF}, plain[:10]} {
		exifOrientation(junk) // must not panic
	}
}

func TestRejectsNonImages(t *testing.T) {
	if _, err := prepareImage([]byte("not an image at all")); err == nil {
		t.Fatal("accepted text")
	}
}

func modelDir(t *testing.T) string {
	t.Helper()
	dir := os.Getenv("PHOTOLY_TEST_MODELS") // contains <revision>/tokenizer.json, onnx/...
	if dir == "" {
		t.Skip("set PHOTOLY_TEST_MODELS to a directory holding the pinned model revision")
	}
	return dir
}

func TestTokenizerMatchesHuggingFace(t *testing.T) {
	tok, err := loadTokenizer(filepath.Join(modelDir(t), modelRevision, "tokenizer.json"))
	if err != nil {
		t.Fatal(err)
	}
	for text, want := range loadReference(t).Tokens {
		if got := tok.Encode(text); !slices.Equal(got, want) {
			t.Errorf("%q: got %v, want %v", text, got, want)
		}
	}
	ids, err := tok.inputIDs("A Cup Of Coffee")
	if err != nil || len(ids) != maxTokens || ids[maxTokens-1] != 0 {
		t.Fatalf("inputIDs: %v %v", ids, err)
	}
	for _, q := range []string{"", string(make([]byte, maxQueryBytes+1)), strings.Repeat("dog cat ", 40)} {
		if _, err := tok.inputIDs(q); err == nil {
			t.Errorf("accepted %d-byte query", len(q))
		}
	}
}

func cosine(a, b []float32) float64 {
	var dot float64
	for i := range a {
		dot += float64(a[i]) * float64(b[i])
	}
	return dot
}
